import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 5 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"5","title":"Page 5 | Home","prev":"/page/4/","next":"/page/6/","posts":[{"title":"网页调用摄像头读取QR code","url":"/posts/2022-12-17-web-qr-reader/","date":"2022-12-17 17:29","tags":["qrcode"],"html":"<p>2022 年也要结束了，博客不能停更。最近项目中有读取 QR 码的需求，于是便调研了下如何实现这个功能，顺便写篇博客记录下。</p>\\n<h2 id=\\"现成-react-框架\\" tabindex=\\"-1\\">现成 React 框架 <a class=\\"header-anchor\\" href=\\"#现成-react-框架\\" aria-label=\\"Permalink to &quot;现成 React 框架&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先调研了别人封装好的现成框架，<a href=\\"https://github.com/react-qr-reader/react-qr-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">React QR Reader</a>。这个框架看起来还挺流行的，可是最新版本的发布已经是 2019 年了。\\n而且有一个致命的 BUG 就是在开启摄像头之后无法关闭。必须重新刷新页面才行，这是不能接受的。</p>\\n<h2 id=\\"低层封装框架\\" tabindex=\\"-1\\">低层封装框架 <a class=\\"header-anchor\\" href=\\"#低层封装框架\\" aria-label=\\"Permalink to &quot;低层封装框架&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>发现大家基本都是调用<a href=\\"https://github.com/zxing-js/browser\\" target=\\"_blank\\" rel=\\"noreferrer\\">@zxing/browser</a>来完成核心功能的。于是我也使用这个框架封装一个不就好了。\\n首先安装相关依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> @zxing/browser</span><span style=\\"color:#032F62\\"> @zxing/library</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>具体的封装代码如下：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> QrReader</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IQrReaderProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  videoId </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'video'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scanDelay </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 500</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  constraints </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    facingMode: </span><span style=\\"color:#032F62\\">'environment'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  className </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  onResult</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> stopRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> videoRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLVideoElement</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (videoRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> codeReader</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> BrowserQRCodeReader</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">undefined</span><span style=\\"color:#24292E\\">, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        delayBetweenScanAttempts: scanDelay</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      stopRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      codeReader</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        .</span><span style=\\"color:#6F42C1\\">decodeFromConstraints</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            video: constraints</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          videoRef.current,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          (</span><span style=\\"color:#E36209\\">result</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">error</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">controls</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            onResult </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> onResult</span><span style=\\"color:#24292E\\">(result, error, controls);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            if</span><span style=\\"color:#24292E\\"> (stopRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              controls.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        )</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        .</span><span style=\\"color:#6F42C1\\">catch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">error</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          onResult </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> onResult</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">undefined</span><span style=\\"color:#24292E\\">, error);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      stopRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [videoId, scanDelay, constraints, onResult]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{</span><span style=\\"color:#6F42C1\\">cls</span><span style=\\"color:#24292E\\">(styles.reader, className)}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.container}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#005CC5\\">ViewFinder</span><span style=\\"color:#24292E\\"> /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#22863A\\">video</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          muted</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{videoRef}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.video}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            transform:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              constraints?.facingMode </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'user'</span><span style=\\"color:#D73A49\\"> ?</span><span style=\\"color:#032F62\\"> 'scaleX(-1)'</span><span style=\\"color:#D73A49\\"> :</span><span style=\\"color:#032F62\\"> 'none'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br></div></div><p>这里使用了 <code>stopRef</code> 来标记组件的销毁并停止调用摄像头。本身封装也不复杂，没必要使用别人封装的轮子。完整的代码在<a href=\\"https://github.com/acgotaku/simple-qr-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">simple-qr-reader</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端生态非常完善，使用现成的库就可以非常方便的实现调用摄像头读取二维码功能。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://zenn.dev/terrierscript/articles/2020-12-22-zxing-browser-react-qr-code-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">@zxing/browser と React の組み合わせで QR Code Reader 作る</a></p>\\n"},{"title":"如何使用TypeScript进行后端开发","url":"/posts/2022-10-29-typescript-backend/","date":"2022-10-29 11:47","tags":["TypeScript"],"html":"<p>我们经常使用 TypeScript 进行开发，webpack 会自动帮我们编译成浏览器可以执行的 JS 文件。相关的开发工具也很完善，但是进行后端开发的资料就比较少了，我们来讲解下如何使用 TypeScript 进行后端开发。</p>\\n<h2 id=\\"开发环境自动重新加载\\" tabindex=\\"-1\\">开发环境自动重新加载 <a class=\\"header-anchor\\" href=\\"#开发环境自动重新加载\\" aria-label=\\"Permalink to &quot;开发环境自动重新加载&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端有 <a href=\\"https://webpack.js.org/concepts/hot-module-replacement/\\" target=\\"_blank\\" rel=\\"noreferrer\\">HMR</a> 技术可以实在自动热加载。后端实现这个功能其实也很简单。 首先需要按照 <code>nodemon</code> 和 <code>ts-node</code>。\\n我们使用 pnpm 进行包管理。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> nodemon</span><span style=\\"color:#032F62\\"> ts-node</span><span style=\\"color:#005CC5\\"> -D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后在 <code>package.json</code> 添加命令。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">nodemon</span><span style=\\"color:#032F62\\"> src/index.ts</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p><code>nodemon</code> 可以完成对文件的监控并且自动 reload，<code>ts-node</code> 完成对 TypeScript 的支持。并且不需要配置，<code>nodemon</code> 会自动调用 <code>ts-node</code>。</p>\\n<h2 id=\\"支持绝对路径引用\\" tabindex=\\"-1\\">支持绝对路径引用 <a class=\\"header-anchor\\" href=\\"#支持绝对路径引用\\" aria-label=\\"Permalink to &quot;支持绝对路径引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端开发中也经常使用绝对路径，所以希望后端也能使用绝对路径。TypeScript 默认不支持绝对路径的使用，我们需要引用第三方来完成这个操作。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> ttypescript</span><span style=\\"color:#032F62\\"> typescript-transform-paths</span><span style=\\"color:#005CC5\\"> -D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>ttypescript 支持在 build 过程中添加插件来完成很多功能，绝对路径转换成相对路径就是其中一个功能， typescript-transform-paths 这个插件就是用来完成绝对路径映射的。我们需要在 <code>tsconfig.json</code> 中进行相关的配置。</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"ts-node\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"transpileOnly\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"require\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"typescript-transform-paths/register\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"compilerOptions\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"target\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"ESNext\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"module\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"commonjs\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"moduleResolution\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"Node\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"outDir\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"dist\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"resolveJsonModule\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"skipLibCheck\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"experimentalDecorators\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"emitDecoratorMetadata\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"esModuleInterop\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"allowSyntheticDefaultImports\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"baseUrl\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\".\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"paths\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">      \\"@/*\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"src/*\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"plugins\\"</span><span style=\\"color:#24292E\\">: [{ </span><span style=\\"color:#005CC5\\">\\"transform\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"typescript-transform-paths\\"</span><span style=\\"color:#24292E\\"> }]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"include\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"src\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br></div></div><p>首先在 <code>paths</code> 字段下，映射文件夹路径，这样就可以使用 <code>@/posts/index.ts</code> 这种格式来引用模块。当然路径映射在开发环境下需要 <code>ts-node</code> 的支持，我们在 <code>ts-node</code> 的 <code>require</code> 字段上引用我们安装的插件。最后是编译成 JS 文件的过程中添加绝对路径的支持。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">ttsc</span><span style=\\"color:#005CC5\\"> -p</span><span style=\\"color:#032F62\\"> tsconfig.json</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>使用增强版 <code>ttsc</code> 来完成路径的转换，可以看到生成的 JS 文件中已经是正常的相对路径引用了，前端的时候大多数都是 webpack 完成打包的，后端的话可以直接使用 <code>ttsc</code> 来完成编译过程。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>TypeScript 在类型定义上的支持可以让我们很方便开发大型项目，后端支持了 reload 和绝对路径之后开发效率也可以大大提高。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://chaika.hatenablog.com/entry/2021/12/20/083000\\" target=\\"_blank\\" rel=\\"noreferrer\\">ts-node で path alias が効かないにハマる</a></p>\\n<p><a href=\\"https://github.com/acgotaku/mapdoge-bot\\" target=\\"_blank\\" rel=\\"noreferrer\\">mapdoge-bot</a></p>\\n"},{"title":"如何编写Telegram Bot","url":"/posts/2022-09-24-telegram-bot/","date":"2022-09-24 11:07","tags":["bot"],"html":"<p>最近在处理如何把经纬度转换成日本的 MAPCODE 的问题。在外出行的时候，经常使用的设备都是手机，如何在手机上方便的计算旅游景点的 MAPCODE 然后使用车载导航呢？\\n我的想法是做一个 Telegram Bot，输入景点的 <a href=\\"https://maps.google.com/pluscodes/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Plus Code</a>, 然后返回 MAPCODE。</p>\\n<h2 id=\\"申请-bot\\" tabindex=\\"-1\\">申请 Bot <a class=\\"header-anchor\\" href=\\"#申请-bot\\" aria-label=\\"Permalink to &quot;申请 Bot&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先，你要去找 <a href=\\"https://t.me/botfather\\" target=\\"_blank\\" rel=\\"noreferrer\\">BotFather</a>申请 Bot。 通过简单的对话就可以创建 Bot。使用 <code>/start</code> 命令可以查看所有支持的指令。</p>\\n<p>输入， <code>/newbot</code> 就可以创建 Bot 了，通过对话模式可以设定 Bot 的名字。然后你可以得到一个属于这个 Bot 的 token，格式类似于 <code>577XXXXX:AAEMUXqXrgRE9R2jPcOXXXXX</code>。\\n拿到这个 token 就可以构建 Bot 了。</p>\\n<h2 id=\\"构建-bot-api\\" tabindex=\\"-1\\">构建 Bot API <a class=\\"header-anchor\\" href=\\"#构建-bot-api\\" aria-label=\\"Permalink to &quot;构建 Bot API&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Bot API 本质是 HTTPS API，通过构建请求来实现功能。不过构造 HTTPS 请求本身很枯燥，已经有很多现成的框架可供我们使用。本人擅长使用 JavaScript，所以选择了 <a href=\\"https://github.com/telegraf/telegraf\\" target=\\"_blank\\" rel=\\"noreferrer\\">telegraf.js</a> 这个框架。</p>\\n<h2 id=\\"bot-代码示例\\" tabindex=\\"-1\\">Bot 代码示例 <a class=\\"header-anchor\\" href=\\"#bot-代码示例\\" aria-label=\\"Permalink to &quot;Bot 代码示例&quot;\\">&ZeroWidthSpace;</a></h2>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">import</span><span style=\\"color:#24292E\\"> { Telegraf } </span><span style=\\"color:#D73A49\\">from</span><span style=\\"color:#032F62\\"> 'telegraf'</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> bot</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> Telegraf</span><span style=\\"color:#24292E\\">(process.env.</span><span style=\\"color:#005CC5\\">BOT_TOKEN</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">bot.</span><span style=\\"color:#6F42C1\\">start</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">ctx</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> message</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#032F62\\"> \`I can help you to query MAPCODE with Telegram.</span><span style=\\"color:#005CC5\\">\\\\n</span><span style=\\"color:#032F62\\">You can copy plus code from Google Maps and paste it to tell me.\`</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ctx.</span><span style=\\"color:#6F42C1\\">reply</span><span style=\\"color:#24292E\\">(message);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">bot.</span><span style=\\"color:#6F42C1\\">help</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">ctx</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ctx.</span><span style=\\"color:#6F42C1\\">replyWithMarkdownV2</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">    'Send me a [plus code](https://maps.google.com/pluscodes/)'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  ctx.</span><span style=\\"color:#6F42C1\\">reply</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">\`MapDoge Version \${</span><span style=\\"color:#24292E\\">process</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#24292E\\">env</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#24292E\\">npm_package_version</span><span style=\\"color:#032F62\\">}\`</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">});</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">bot.</span><span style=\\"color:#6F42C1\\">launch</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6A737D\\">// Enable graceful stop</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">process.</span><span style=\\"color:#6F42C1\\">once</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGINT'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> bot.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGINT'</span><span style=\\"color:#24292E\\">));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">process.</span><span style=\\"color:#6F42C1\\">once</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGTERM'</span><span style=\\"color:#24292E\\">, () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> bot.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">'SIGTERM'</span><span style=\\"color:#24292E\\">));</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br></div></div><p>Telegram Bot 默认都支持 <code>/start</code> 和 <code>/help</code> 命令。所以我就贴出了这两个命令的简单写法。使用成熟的框架可以大大简化编写 Bot 的复杂度。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Telegram Bot 有完善的文档和生态，编写一个 Bot 并没有想象的那么难。大家都可以尝试下，非常方便实现在手机端的一些自定义功能。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://core.telegram.org/bots/samples\\" target=\\"_blank\\" rel=\\"noreferrer\\">Bot Code Examples</a></p>\\n<p><a href=\\"https://github.com/acgotaku/mapdoge-bot\\" target=\\"_blank\\" rel=\\"noreferrer\\">mapdoge-bot</a></p>\\n"}]},"relativePath":"page/5/index.md","filePath":"page/[page].md"}`),p={name:"page/5/index.md"};function l(e,o,r,c,t,i){return n(),a("div")}const d=s(p,[["render",l]]);export{b as __pageData,d as default};
